NRU = 'https://www.aph.gov.au/Parliamentary_Business/Committees/Joint/Treaties/Nauru-AusTreaty/Media_Releases'


def COMPACT(amount, nation):
    return R('bilat', 'Enacted', 'Compact of Free Association, economic assistance', 'United States · Compact of Free Association Amendments Act of 2024 · Signed 9 March 2024 · Through 2043', amount,
             'Twenty years of US economic assistance to %s under the renewed Compact; $7.1 billion in all for Micronesia, the Marshall Islands and Palau.' % nation,
             ['United States'], COFA, note='All three nations: $7.1 billion')


